// Core tests: the 8 literal core cases from the fixed spec's fixtures.json
// (vendored verbatim at test/fixtures.json from spec candidate
// 2a24708ad8b9e10c5631f58e896dd005b069eb8b; expected values taken verbatim,
// never generated by the product), plus hand-derived boundary and
// validation-order cases. Every extra expected value below was computed
// from the SPEC's stated integer formulas by an independent scratch
// implementation before the product code existed.

import assert from "node:assert/strict";
import test from "node:test";
import { ENERGY_FACTORS, run } from "../public/js/core/macro.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

test("structural invariants hold on every success fixture", () => {
  for (const entry of coreCases) {
    if (!entry.expected.ok) continue;
    const { result } = run(entry.input);
    assert.equal(result.deltaKcal, result.impliedKcal - result.calories, entry.id);
    let implied = 0;
    for (const macro of result.macros) {
      assert.equal(macro.kcal, ENERGY_FACTORS[macro.id] * macro.grams, entry.id);
      assert.ok(macro.grams >= 0, entry.id);
      implied += macro.kcal;
    }
    assert.equal(result.impliedKcal, implied, entry.id);
    if (result.meals !== null) {
      for (const id of ["protein", "carbs", "fat"]) {
        const daily = result.macros.find((macro) => macro.id === id).grams;
        assert.equal(
          result.meals.items.reduce((sum, item) => sum + item[id], 0),
          daily,
          entry.id,
        );
      }
      assert.equal(
        result.meals.items.reduce((sum, item) => sum + item.kcal, 0),
        result.impliedKcal,
        entry.id,
      );
    }
  }
});

// Hand-derived endpoint: 800 kcal balanced. Grams 60 / 80 / 27 -> implied
// 803, residual -3, largest is carbs (320 kcal share), deltaG = -1 ->
// carbs 79, implied 799, delta -1.
test("hand-derived endpoint: 800 kcal balanced", () => {
  assert.deepEqual(
    run({ calories: "800", preset: "balanced", proteinPct: "", carbsPct: "", fatPct: "", meals: "" }),
    {
      ok: true,
      result: {
        calories: 800,
        ratios: { protein: 30, carbs: 40, fat: 30 },
        macros: [
          { id: "protein", pct: 30, targetKcal: 240, grams: 60, kcal: 240 },
          { id: "carbs", pct: 40, targetKcal: 320, grams: 79, kcal: 316 },
          { id: "fat", pct: 30, targetKcal: 240, grams: 27, kcal: 243 },
        ],
        adjustedMacro: "carbs",
        impliedKcal: 799,
        deltaKcal: -1,
        meals: null,
      },
    },
  );
});

