// Hand-derived tie case (SPEC tests section): custom 40/40/20 at
// 1,650 kcal. Protein and carbs tie on T*pct (660); the fixed order takes
// protein. Grams 165 / 165 / 37 -> implied 1653, residual -3, deltaG for
// protein = -1 -> 164, implied 1649.
test("hand-derived: largest-macro tie 40/40/20 resolves to protein", () => {
  assert.deepEqual(
    run({
      calories: "1650",
      preset: "custom",
      proteinPct: "40",
      carbsPct: "40",
      fatPct: "20",
      meals: "",
    }),
    {
      ok: true,
      result: {
        calories: 1650,
        ratios: { protein: 40, carbs: 40, fat: 20 },
        macros: [
          { id: "protein", pct: 40, targetKcal: 660, grams: 164, kcal: 656 },
          { id: "carbs", pct: 40, targetKcal: 660, grams: 165, kcal: 660 },
          { id: "fat", pct: 20, targetKcal: 330, grams: 37, kcal: 333 },
        ],
        adjustedMacro: "protein",
        impliedKcal: 1649,
        deltaKcal: -1,
        meals: null,
      },
    },
  );
});

// Hand-derived meals endpoints at 2,400 kcal balanced (grams 180/240/80,
// no drift): one meal takes everything; six meals split fat 80 as
// 14/14/13/13/13/13 with the remainder to the earlier meals.
test("hand-derived: meals 1 and meals 6 splits", () => {
  const base = { calories: "2400", preset: "balanced", proteinPct: "", carbsPct: "", fatPct: "" };
  const one = run({ ...base, meals: "1" });
  assert.equal(one.ok, true);
  assert.deepEqual(one.result.meals, {
    count: 1,
    items: [{ index: 1, protein: 180, carbs: 240, fat: 80, kcal: 2400 }],
  });
  const six = run({ ...base, meals: "6" });
  assert.equal(six.ok, true);
  assert.deepEqual(six.result.meals, {
    count: 6,
    items: [
      { index: 1, protein: 30, carbs: 40, fat: 14, kcal: 406 },
      { index: 2, protein: 30, carbs: 40, fat: 14, kcal: 406 },
      { index: 3, protein: 30, carbs: 40, fat: 13, kcal: 397 },
      { index: 4, protein: 30, carbs: 40, fat: 13, kcal: 397 },
      { index: 5, protein: 30, carbs: 40, fat: 13, kcal: 397 },
      { index: 6, protein: 30, carbs: 40, fat: 13, kcal: 397 },
    ],
  });
});

const valid = {
  calories: "2000",
  preset: "balanced",
  proteinPct: "",
  carbsPct: "",
  fatPct: "",
  meals: "",
};
const errorOf = (input) => run(input).error;

test("SCHEMA: non-objects, arrays, missing, extra, wrong types, accessors", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("balanced"), schema);
  assert.deepEqual(errorOf(["2000", "balanced"]), schema);
  assert.deepEqual(
    errorOf({ calories: "2000", preset: "balanced", proteinPct: "", carbsPct: "", fatPct: "" }),
    schema,
  );
  assert.deepEqual(errorOf({ ...valid, extra: "1" }), schema);
  assert.deepEqual(errorOf({ ...valid, calories: 2000 }), schema);
  assert.deepEqual(errorOf({ ...valid, preset: null }), schema);
  const withAccessor = { ...valid };
  Object.defineProperty(withAccessor, "meals", {
    enumerable: true,
    get() {
      return "";
    },
  });
  assert.deepEqual(errorOf(withAccessor), schema);
});

test("named presets ignore the pct fields completely, even garbage", () => {
  const result = run({ ...valid, proteinPct: "junk!!", carbsPct: "999999999", fatPct: "-5" });
  assert.deepEqual(result, run(valid));
  assert.equal(result.ok, true);
});

test("field order: calories, preset, custom pct + sum, then meals", () => {
  assert.deepEqual(errorOf({ ...valid, calories: "799", preset: "vegan" }), {
    code: "RANGE",
    field: "calories",
    row: null,
  });
  assert.deepEqual(
    errorOf({ ...valid, preset: "vegan", proteinPct: "x", meals: "9" }),
    { code: "ENUM", field: "preset", row: null },
  );
  assert.deepEqual(
    errorOf({
      ...valid,
      preset: "custom",
      proteinPct: "101",
      carbsPct: "0",
      fatPct: "0",
      meals: "9",
    }),
    { code: "RANGE", field: "proteinPct", row: null },
    "a single pct of 101 fails RANGE before the sum is considered",
  );
  assert.deepEqual(
    errorOf({
      ...valid,
      preset: "custom",
      proteinPct: "40",
      carbsPct: "40",
      fatPct: "30",
      meals: "9",
    }),
    { code: "RATIO_SUM", field: null, row: null },
    "the ratio sum is checked before meals",
  );
});

test("per-field order: capacity before empty before grammar before range", () => {
  assert.deepEqual(errorOf({ ...valid, calories: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "calories",
    row: null,
  });
  assert.deepEqual(
    errorOf({ ...valid, preset: "custom", proteinPct: "123456789", carbsPct: "0", fatPct: "0" }),
    { code: "INPUT_LIMIT", field: "proteinPct", row: null },
  );
  assert.deepEqual(errorOf({ ...valid, calories: "" }), {
    code: "EMPTY",
    field: "calories",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, preset: "" }), {
    code: "EMPTY",
    field: "preset",
    row: null,
  });
  assert.deepEqual(
    errorOf({ ...valid, preset: "custom", proteinPct: "", carbsPct: "50", fatPct: "50" }),
    { code: "EMPTY", field: "proteinPct", row: null },
  );
  assert.deepEqual(errorOf({ ...valid, calories: "99999999" }), {
    code: "RANGE",
    field: "calories",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, calories: "10001" }), {
    code: "RANGE",
    field: "calories",
    row: null,
  });
});

test("integer grammar rejects decimals, signs, spaces, leading zeros, exponents", () => {
  for (const bad of ["2000.5", "0100", " 2000", "2000 ", "+2000", "-2000", "2e3", "2,000", "２０００"]) {
    assert.deepEqual(
      errorOf({ ...valid, calories: bad }),
      { code: "INTEGER_FORMAT", field: "calories", row: null },
      `calories ${JSON.stringify(bad)}`,
    );
  }
  assert.deepEqual(errorOf({ ...valid, meals: "1.5" }), {
    code: "INTEGER_FORMAT",
    field: "meals",
    row: null,
  });
});

test("ratio sums of 99 and 101 fail RATIO_SUM after each pct passes", () => {
  const custom = { ...valid, preset: "custom" };
  assert.deepEqual(errorOf({ ...custom, proteinPct: "33", carbsPct: "33", fatPct: "33" }), {
    code: "RATIO_SUM",
    field: null,
    row: null,
  });
  assert.deepEqual(errorOf({ ...custom, proteinPct: "34", carbsPct: "33", fatPct: "34" }), {
    code: "RATIO_SUM",
    field: null,
    row: null,
  });
});

test("preset has no 8-unit capacity: long non-enum values fail ENUM, not INPUT_LIMIT", () => {
  assert.deepEqual(errorOf({ ...valid, preset: "balancedx" }), {
    code: "ENUM",
    field: "preset",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, preset: "x".repeat(100) }), {
    code: "ENUM",
    field: "preset",
    row: null,
  });
});

test("meals edges: 0 and 7 are RANGE; a long digit string is RANGE (no capacity pinned for meals)", () => {
  assert.deepEqual(errorOf({ ...valid, meals: "0" }), {
    code: "RANGE",
    field: "meals",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, meals: "7" }), {
    code: "RANGE",
    field: "meals",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, meals: "123456789" }), {
    code: "RANGE",
    field: "meals",
    row: null,
  });
});

test("lone surrogates fail the field grammar/enum, never crash", () => {
  assert.deepEqual(errorOf({ ...valid, calories: "2000\uD800" }), {
    code: "INTEGER_FORMAT",
    field: "calories",
    row: null,
  });
  assert.deepEqual(errorOf({ ...valid, preset: "balanced\uD800" }), {
    code: "ENUM",
    field: "preset",
    row: null,
  });
  assert.deepEqual(
    errorOf({ ...valid, preset: "custom", proteinPct: "5\uD800", carbsPct: "50", fatPct: "45" }),
    { code: "INTEGER_FORMAT", field: "proteinPct", row: null },
  );
});

test("invariants over a deterministic pseudo-random sweep", () => {
  let seed = 1234567;
  const next = () => {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    return seed;
  };
  const presets = ["balanced", "high-protein", "low-carb", "keto"];
  for (let i = 0; i < 500; i += 1) {
    const calories = 800 + (next() % 9201);
    let input;
    if (next() % 2 === 0) {
      const a = next() % 101;
      const b = next() % (101 - a);
      input = {
        calories: String(calories),
        preset: "custom",
        proteinPct: String(a),
        carbsPct: String(b),
        fatPct: String(100 - a - b),
        meals: ["", "1", "2", "3", "4", "5", "6"][next() % 7],
      };
    } else {
      input = {
        calories: String(calories),
        preset: presets[next() % 4],
        proteinPct: "",
        carbsPct: "",
        fatPct: "",
        meals: ["", "1", "2", "3", "4", "5", "6"][next() % 7],
      };
    }
    const outcome = run(input);
    assert.equal(outcome.ok, true, JSON.stringify(input));
    const { result } = outcome;
    assert.equal(result.deltaKcal, result.impliedKcal - result.calories);
    // The pre-adjustment residual is bounded by |R| <= 8 and the drift
    // adjustment moves at most 2 grams, so the final delta stays small.
    assert.ok(Math.abs(result.deltaKcal) <= 8, JSON.stringify(input));
    for (const macro of result.macros) assert.ok(macro.grams >= 0);
    if (result.meals !== null) {
      for (const id of ["protein", "carbs", "fat"]) {
        const daily = result.macros.find((macro) => macro.id === id).grams;
        assert.equal(result.meals.items.reduce((sum, item) => sum + item[id], 0), daily);
      }
      assert.equal(
        result.meals.items.reduce((sum, item) => sum + item.kcal, 0),
        result.impliedKcal,
      );
    }
  }
});
